const resumen = $('Resumen de Ventas').first().json;
const topProductos = $('Top 5 Productos').all().map(i => i.json);

const texto = `Resumen de ventas del periodo:\n` +
  `- Facturas: ${resumen.invoices}\n` +
  `- Total vendido: ${resumen.total_sales}\n` +
  `- Margen total: ${resumen.total_margin}\n` +
  `- Top productos: ${topProductos.map(p => `${p.item_name} (${p.qty_sold} und, ${p.total_sales})`).join('; ')}`;

return [{ json: { resumen, topProductos, texto } }];
